/* EpnMapper.selectEpnList : EPN 리스트 조회 */
SELECT epn.REGISTER_DATE_TIME ,epn.SEND_DATE_TIME ,epn.CLEARANCE_TYPE ,epn.MF_TS_YN ,epn.HBL_NO ,epn.LICENSE_NO ,epn.SHIPPER_NAME ,epn.SHIPPER_BUSINESS_ID ,epn.PIECES ,epn.UNIT_PIECES ,epn.GWT ,epn.HS_CODE ,epn.LICENSE_REMARK ,epn.TS_REGISTER_INFO ,epn.CHECK_REQUEST ,epn.CHECK_RESULT ,epn.INSPECTION_REQUEST ,epn.INSPECTION_RESULT ,epn.EMERGENCY_YN ,epn.ECM_TYPE ,epn.EPN_JOB_NO ,epn.PACKING_CODE ,epn.PACKING_PIECES ,epn.SPLIT_YN ,epn.SPLIT_SEQ ,(SELECT TOP 1 OD_JOB_NO FROM TB_ECM_OD od WHERE od.HBL_NO = epn.HBL_NO and od.BOUND_TYPE = 'EXP' and CONVERT(varchar(10), REGISTER_DATE_TIME , 23) = CONVERT(varchar(10), DATEADD(HOUR, 9, GETDATE()) ,23)) AS OD_JOB_NO ,(SELECT TOP 1 CONVERT(varchar(10), REGISTER_DATE_TIME , 23) FROM TB_ECM_OD od WHERE od.HBL_NO = epn.HBL_NO and od.BOUND_TYPE = 'EXP' and CONVERT(varchar(10), REGISTER_DATE_TIME , 23) = CONVERT(varchar(10), DATEADD(HOUR, 9, GETDATE()) ,23)) AS OD_REGISTER_DATE_TIME ,(SELECT USER_LOGIN_ID FROM TB_SMS_USER WHERE ENT_CODE = #{srchEntCode} AND USER_ID = epn.REGISTER_USER_ID) AS REGISTER_USER_NAME ,epn.OB_DATE FROM TB_ECM_EPN epn WHERE 1 = 1
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND epn.CLEARANCE_TYPE = #{srchClearanceType}
AND epn.SHIPPER_NAME = #{shipperName}
AND epn.LICENSE_REMARK = #{licenseRemark}
AND epn.MF_TS_YN = #{mfTsYn}

