,''
,'0' ,'0' ,'0' ,'0' ,'0' ,'0' ,'0' ,'' ,#{destCountry} ,'' ,'Y' ,'N' ,'' ,#{updateUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,#{updateUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,'' ,''
,#{shipperBusinessId}
,''
