/* .selectManifestLicenseTargetCount */
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT COUNT(1) CNT
FROM TB_ECM_EPN epn
WHERE 1 = 1



            AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
            AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))


            AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
            AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})







            AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')




                    AND ${srchNoType} IN (#{item})


                    AND ${srchNoType} = #{srchNo}







    AND epn.CLEARANCE_TYPE = #{srchClearanceType}


    AND epn.SHIPPER_NAME = #{shipperName}


    AND epn.LICENSE_REMARK = #{licenseRemark}


    AND epn.MF_TS_YN = #{mfTsYn}

