/* EpnMapper.updateOdShipperInfo */
UPDATE TB_ECM_OD
SET
UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
,ECM_TYPE = 'A'

    ,SHIPPER_BUSINESS_ID = #{shipperBusinessId}
    ,CUSTOMS_ID_TYPE = '04'


    ,ALLOWED_ITEM_CODE = #{hsCode}


    ,SHIPPER_NAME = #{shipperName}

WHERE OD_JOB_NO = #{odJobNo}

