/* EpnMapper.selectManifestLicenseList */ SELECT epn.EPN_JOB_NO as epnJobNo ,epn.REGISTER_DATE_TIME ,epn.SEND_DATE_TIME ,epn.CLEARANCE_TYPE as clearanceType ,epn.MF_TS_YN as mfTsYn ,epn.HBL_NO as hblNo ,epn.LICENSE_NO as licenseNo ,epn.SHIPPER_NAME ,epn.SHIPPER_BUSINESS_ID as shipperBusinessId ,epn.PIECES as pieces ,epn.UNIT_PIECES as unitPieces ,epn.GWT as gwt ,epn.LICENSE_REMARK ,epn.TS_REGISTER_INFO ,epn.CHECK_REQUEST ,epn.CHECK_RESULT ,epn.INSPECTION_REQUEST ,epn.INSPECTION_RESULT ,epn.EMERGENCY_YN ,epn.ECM_TYPE ,epn.EPN_JOB_NO ,epn.PACKING_CODE as packingCode ,epn.PACKING_PIECES as packingPieces ,epn.SPLIT_YN as splitYn ,epn.SPLIT_SEQ as splitSeq ,(SELECT USER_LOGIN_ID FROM TB_SMS_USER WHERE ENT_CODE = #{srchEntCode} AND USER_ID = epn.REGISTER_USER_ID) AS REGISTER_USER_NAME ,(SELECT TOP 1 OD_JOB_NO FROM TB_ECM_OD od WHERE od.HBL_NO = epn.HBL_NO and od.BOUND_TYPE = 'EXP' and CONVERT(varchar(10), od.REGISTER_DATE_TIME , 23) = CONVERT(varchar(10), DATEADD(HOUR, 9, GETDATE()) ,23)) AS odJobNo ,(SELECT TOP 1 CONVERT(varchar(10), REGISTER_DATE_TIME , 23) AS REGISTER_DATE_TIME FROM TB_ECM_OD od WHERE od.HBL_NO = epn.HBL_NO AND od.BOUND_TYPE = 'EXP' and CONVERT(varchar(10), od.REGISTER_DATE_TIME , 23) = CONVERT(varchar(10), DATEADD(HOUR, 9, GETDATE()) ,23)) AS odRegisterDateTime FROM TB_ECM_EPN epn WHERE 1 = 1
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND epn.CLEARANCE_TYPE = #{srchClearanceType}
AND epn.SHIPPER_NAME = #{shipperName}
AND epn.LICENSE_REMARK = #{licenseRemark}
AND epn.MF_TS_YN = #{mfTsYn}

/* EpnMapper.selectOdLicenseInfo */
SELECT
    TOP 1
    teol.LICENSE_NO
    ,teol.OD_JOB_NO
FROM
    TB_ECM_OD_LICENSE teol
WHERE
    teol.OD_JOB_NO = #{odJobNo}
    AND teol.LICENSE_NO = #{licenseNo}

mapper.update:
UPDATE
    TB_ECM_OD_LICENSE
  SET
    PIECES = #{pieces}
    ,UNIT_PIECES = #{unitPieces}
    ,GWT = #{gwt}
    ,PARTIAL_YN = #{splitYn}
    ,PARTIAL_SEQ = #{splitSeq}
    ,COMBINE_TYPE_A_Z = #{packingCode}
    ,COMBINE_PIECES = #{packingPieces}
WHERE
    OD_JOB_NO = #{odJobNo}
    AND LICENSE_NO = #{licenseNo}

mapper.insert:
INSERT
INTO TB_ECM_OD_LICENSE (
    OD_JOB_NO,
    LICENSE_NO,
    PIECES,
    UNIT_PIECES,
    GWT,
    COMBINE_TYPE_A_Z,
    COMBINE_PIECES,
    PARTIAL_YN,
    PARTIAL_SEQ,
    REGISTER_USER_ID,
    REGISTER_DATE_TIME,
    UPDATE_USER_ID,
    UPDATE_DATE_TIME
) VALUES(
    #{odJobNo}
    ,#{licenseNo}
    ,#{pieces}
    ,#{unitPieces}
    ,#{gwt}
    ,#{packingCode}
    ,#{packingPieces}
    ,#{splitYn}
    ,#{splitSeq}
    ,#{updateUserId}
    ,DATEADD(HOUR, ${gmtTime}, GETDATE())
    ,#{updateUserId}
    ,DATEADD(HOUR, ${gmtTime}, GETDATE())
)

