/* EpnMapper.updateEpnMfTsYn */
UPDATE TB_ECM_EPN
    SET MF_TS_YN = 'Y'
WHERE
    EPN_JOB_NO = #{epnJobNo}
    AND HBL_NO = #{hblNo}

/* EpnMapper.updateOdIert */
UPDATE TB_ECM_OD
  SET BL_TYPE_IERT = 'R'
WHERE OD_JOB_NO = #{odJobNo}
